/* Unit table: name, position, order target and order, and fuel, ammo and
 * food percentages. Own units need an eligible selection; enemy units show
 * the full row only when flagged (+15 bit 5), otherwise just the position.
 * Local names follow C 6.0a's frame slot order (name sum mod 16). */
void opeu_tbl_draw_units(uint8_t ds[65536], HostEvent event, uint16_t scratch,
                         uint8_t column, uint8_t first, uint8_t row,
                         uint8_t last, uint8_t flags) {
  TEXT_PTR an;
  TEXT_PTR bm;
  uint8_t  cl;
  uint8_t  p;
  uint8_t  a;
  UNIT_PTR b;
  uint16_t c;
  uint16_t d;
  uint8_t  e;
  uint8_t  f;
  uint16_t g;
  uint8_t  h;
  BUFFER(i, 32, 4);
  TEXT_PTR   j;
  uint8_t    k;
  uint16_t   l;
  WINDOW_PTR m;
  BUFFER(n, 100, 36);
  BUFFER(o, 32, 136);
  m = WINDOW;
  COLUMNS(column, e, row, a, p);
  if (flags & 3) {
    FORMAT(n, UNIT_HEADER);
    POSITION(WIN_COLUMN(m) + e + WIN_X(m) - 0x20, WIN_Y(m) + 1);
    SIDE_COLOR(SIDE);
    PUT_RANGE(n, a, p);
  }
  for (h = first; h <= last; NEXT_UNIT(b), ++h) {
    b = UNIT_AT(h);
    f = UNIT_SIDE(b);
    if (flags & 5) {
      POSITION(WIN_X(m) + 2, (h - TOP) * 17 + WIN_Y(m) + 18);
      SIDE_COLOR(f);
      if (UNIT_FLAGS(b) & 4) {
        if (f == SIDE && (UNIT_FLAGS(b) & 1))
          UI_TEXT(UNIT_MARK);
        PRINT(UNIT_LABEL, UNIT_NAME(b, i));
      } else
        UI_TEXT(UNIT_EMPTY);
    }
    if (!(UNIT_FLAGS(b) & 4) || (f == SIDE && !ELIGIBLE(b)))
      COPY(n, UNIT_BLANK);
    else if ((f == SIDE && ELIGIBLE(b)) ||
             (f != SIDE && (UNIT_FLAGS(b) & 0x20))) {
      d = DESTINATION(b, k, cl);
      PERCENT(b, c, l, g);
      bm = d ? LOCATION(k, cl, i) : LOCATION(UNIT_X(b), UNIT_Y(b), o);
      j  = LOCATION(UNIT_X(b), UNIT_Y(b), o);
      an = d ? ORDER_NAME(b) : UNIT_WAIT;
      FORMAT(n, UNIT_ROW, j, bm, an, l, c, g);
    } else if (f != SIDE && !(UNIT_FLAGS(b) & 0x20))
      FORMAT(n, UNIT_HIDDEN, LOCATION(UNIT_X(b), UNIT_Y(b), i));
    POSITION(WIN_COLUMN(m) + e + WIN_X(m) - 0x20,
             (h - TOP) * 17 + WIN_Y(m) + 18);
    TEXT_COLOR(7);
    PUT_RANGE(n, a, p);
  }
  TEXT_COLOR(7);
}

/* Unit orders table: unit name and the fixed request text 7b. */
void opeu_tbl_draw_orders(uint8_t ds[65536], HostEvent event, uint16_t scratch,
                          uint8_t column, uint8_t first, uint8_t row,
                          uint8_t last, uint8_t flags) {
  uint8_t  a, b;
  UNIT_PTR c;
  uint8_t  d, e, f;
  BUFFER(g, 32, 4);
  WINDOW_PTR h;
  BUFFER(i, 100, 36);
  h = WINDOW;
  COLUMNS(column, d, row, b, a);
  if (flags & 3) {
    FORMAT(i, ORDER_HEADER);
    POSITION(WIN_COLUMN(h) + d + WIN_X(h) - 0x20, WIN_Y(h) + 1);
    SIDE_COLOR(SIDE);
    PUT_RANGE(i, b, a);
  }
  for (f = first; f <= last; NEXT_UNIT(c), ++f) {
    c = UNIT_AT(f);
    e = UNIT_SIDE(c);
    if (flags & 5) {
      POSITION(WIN_X(h) + 2, (f - TOP) * 17 + WIN_Y(h) + 18);
      SIDE_COLOR(e);
      PRINT(ORDER_LABEL, UNIT_NAME(c, g));
    }
    COPY(i, REQUEST_TEXT(0x7b));
    POSITION(WIN_COLUMN(h) + d + WIN_X(h) - 0x20,
             (f - TOP) * 17 + WIN_Y(h) + 18);
    TEXT_COLOR(7);
    PUT_RANGE(i, b, a);
  }
  TEXT_COLOR(7);
}

